/**
 * Build-time bond snapshot (feature 015-ovdp-data-pages).
 *
 * Emits src/app/features/ovdp/bond-snapshot.data.ts (gitignored, AUTO-GENERATED) so the /ovdp
 * pages prerender with real data and stay meaningful with JavaScript disabled. Source order:
 *
 *   1. GET $BOND_SNAPSHOT_API (default: the public prod endpoint). On success the committed
 *      fallback JSON is refreshed too, so the repo's fallback tracks the last good fetch.
 *   2. On ANY fetch failure: tools/seo/bond-snapshot.fallback.json (committed; seeded from a real
 *      scraper dry-run). The build never breaks offline - it just notes the fallback.
 *
 * Honesty rule: no fabricated data. If the fallback is ever emptied, the pages render an explicit
 * "data unavailable" state (audit A30 accepts data-ovdp-asof OR data-ovdp-empty).
 *
 * Plain Node ESM, no dependencies. Deterministic for a given source payload: fetchedAt comes from
 * the payload (max per-record fetchedAt) or the fallback file, never from the wall clock.
 */
import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = join(__dirname, '..', '..');
const FALLBACK = join(__dirname, 'bond-snapshot.fallback.json');
const OUT_TS = join(ROOT, 'src', 'app', 'features', 'ovdp', 'bond-snapshot.data.ts');
const API = (process.env.BOND_SNAPSHOT_API || 'https://api.investguideua.com/api/v1/bond-prices/latest').trim();
const TIMEOUT_MS = 10000;

const CURRENCIES = new Set(['UAH', 'USD', 'EUR']);

/** Keep only structurally valid records; prices MUST be integers (minor units per 1000 face). */
function sanitize(records) {
  const out = [];
  for (const r of Array.isArray(records) ? records : []) {
    const isin = String(r.isin || '').trim();
    if (!/^[A-Z]{2}[A-Z0-9]{10}$/.test(isin)) continue;
    if (!Number.isInteger(r.sellPriceMinor) || !Number.isInteger(r.buyPriceMinor)) continue;
    if (!Number.isFinite(r.sellYield) || !Number.isFinite(r.buyYield)) continue;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(String(r.maturity || ''))) continue;
    const currency = String(r.currency || '').trim();
    // Never guess a currency: a mislabeled record is worse than a dropped one.
    if (!CURRENCIES.has(currency)) continue;
    out.push({
      isin,
      military: Boolean(r.military),
      currency,
      maturity: r.maturity,
      sellPriceMinor: r.sellPriceMinor,
      buyPriceMinor: r.buyPriceMinor,
      sellYield: r.sellYield,
      buyYield: r.buyYield,
    });
  }
  out.sort((a, b) => a.maturity.localeCompare(b.maturity) || a.isin.localeCompare(b.isin));
  return out;
}

async function fromApi() {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), TIMEOUT_MS);
  try {
    const res = await fetch(API, { signal: controller.signal, headers: { accept: 'application/json' } });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const body = await res.json();
    const bonds = sanitize(body);
    if (!bonds.length) throw new Error('empty payload');
    // fetchedAt: the newest per-record ingest stamp in the payload (server-side UTC), not the clock.
    const fetchedAt = body
      .map((r) => String(r.fetchedAt || ''))
      .filter(Boolean)
      .sort()
      .pop() || null;
    return { fetchedAt, bonds, source: 'api' };
  } finally {
    clearTimeout(timer);
  }
}

function fromFallback() {
  const raw = JSON.parse(readFileSync(FALLBACK, 'utf-8'));
  return { fetchedAt: raw.fetchedAt ?? null, bonds: sanitize(raw.bonds), source: 'fallback' };
}

function emit({ fetchedAt, bonds }) {
  const ts = `// AUTO-GENERATED by tools/seo/fetch-bond-snapshot.mjs - DO NOT EDIT.
// Latest per-ISIN bond quotes bundled at build time so /ovdp pages prerender with data.
// Prices are integer minor units per 1000 face value; yields are reference percentages.

export interface BondSnapshotEntry {
  readonly isin: string;
  readonly military: boolean;
  readonly currency: string;
  /** ISO maturity date (yyyy-MM-dd). */
  readonly maturity: string;
  /** Integer minor units (kopiykas/cents) per 1000 face value. */
  readonly sellPriceMinor: number;
  readonly buyPriceMinor: number;
  /** Reference percentage, e.g. 15.25 = 15.25% p.a. */
  readonly sellYield: number;
  readonly buyYield: number;
}

export interface BondSnapshot {
  /** Server-side ingest stamp of the newest quote (ISO), or null when no data was available. */
  readonly fetchedAt: string | null;
  readonly bonds: readonly BondSnapshotEntry[];
}

export const BOND_SNAPSHOT: BondSnapshot = ${JSON.stringify({ fetchedAt, bonds }, null, 2)};
`;
  mkdirSync(dirname(OUT_TS), { recursive: true });
  writeFileSync(OUT_TS, ts);
}

/**
 * The committed fallback refreshes only on explicit request (BOND_SNAPSHOT_REFRESH_FALLBACK=true,
 * for a deliberate "update the fallback" commit) AND when the payload clears a minimum-record
 * floor - a truncated-but-valid payload must never silently replace a good fallback. Routine dev
 * builds keep `git status` clean.
 */
const REFRESH_FALLBACK = String(process.env.BOND_SNAPSHOT_REFRESH_FALLBACK || '').toLowerCase() === 'true';
const MIN_FALLBACK_RECORDS = 10;

let snapshot;
try {
  snapshot = await fromApi();
  if (REFRESH_FALLBACK && snapshot.bonds.length >= MIN_FALLBACK_RECORDS) {
    writeFileSync(FALLBACK, JSON.stringify({ fetchedAt: snapshot.fetchedAt, bonds: snapshot.bonds }, null, 2) + '\n');
    console.log(`[seo:snapshot] committed fallback refreshed (${snapshot.bonds.length} bonds).`);
  }
} catch (err) {
  if (!existsSync(FALLBACK)) {
    console.error(`[seo:snapshot] API failed (${err.message}) and no fallback exists - cannot continue.`);
    process.exit(1);
  }
  snapshot = fromFallback();
  console.warn(`[seo:snapshot] API unavailable (${err.message}); using committed fallback.`);
}

emit(snapshot);
console.log(
  `[seo:snapshot] ${snapshot.bonds.length} bond(s) from ${snapshot.source}` +
  ` (fetchedAt ${snapshot.fetchedAt ?? 'n/a'}) -> bond-snapshot.data.ts`,
);
